// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 value, uint256 warpTime) public {
        vm.assume(value != 10 ether);
        vm.assume(warpTime > 0);
        vm.warp(warpTime);
        vm.deal(address(this), value);
        address target = address(c);
        bool ok;
        (bool s,) = target.call{value: value}("");
        ok = s;
        assertTrue(!ok, "call with value != 10 ether must revert");
    }
}
